def resume(self, widget):
    cancel = self._printer.get_stat("fast_cancel") or {}
    if cancel.get("phase") == "dock_sensor_hold":
        if not cancel.get("dock_recovery_ready"):
            self._screen.show_popup_message(_("Dock recovery is unavailable. Inspect the tool and cancel the held print."))
            return
        slot = cancel.get("tool", -1) + 1
        label = Gtk.Label(hexpand=True, vexpand=True, wrap=True)
        label.set_text(_("툴 T%d가 거치대에 완전히 들어가 있고 헤드는 비어 있습니까? X0까지의 이동 경로도 확인해 주세요.") % slot)
        buttons = [
            {"name": _("예"), "response": Gtk.ResponseType.YES, "style": "dialog-info"},
            {"name": _("아니요"), "response": Gtk.ResponseType.NO, "style": "dialog-error"},
        ]
        self._gtk.Dialog(_("툴 거치 확인"), buttons, label, self.resume_dock_confirm, cancel["dock_recovery_id"])
        return
    self._screen._send_action(widget, "printer.print.resume", {})
    self._screen.show_all()

def resume_dock_confirm(self, dialog, response_id, recovery_id):
    self._gtk.remove_dialog(dialog)
    if response_id == Gtk.ResponseType.YES:
        self._screen._send_action(None, "printer.gcode.script",
                                  {"script": f"RESUME DOCK_CONFIRMED={recovery_id:d}"})
